const menu=document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname&&!a.hash)a.setAttribute('aria-current','page');a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false');});});
const form=document.querySelector('#enquiry');
let enquiryId=crypto.randomUUID();
const SERVICE_CATEGORIES={"SA visas":"Visa expediting","Waivers":"Visa expediting","Appeals":"Visa expediting","FBI USA clearance":"Police clearance certificate","ZIM clearance":"Police clearance certificate","DHA documents":"Document expediting","USA visa":"Visa expediting","UK visa":"Visa expediting","Schengen visa":"Visa expediting"};
if(form){
 const service=new URLSearchParams(location.search).get('service');
 if([...form.elements.service.options].some(x=>x.value===service))form.elements.service.value=service;
 const params=new URLSearchParams(location.search),requested=params.get('request'),destination=params.get('destination');
 if(destination)form.elements.destination.value=destination.slice(0,100);
 if(requested&&[...form.elements.service.options].some(x=>x.value===requested))form.elements.service.value=requested;
 if(requested){const label=document.querySelector('#requested-service');label.hidden=false;label.textContent='Your enquiry: '+requested.slice(0,150);form.elements.message.value='I would like assistance with '+requested.slice(0,150)+'.\n';}
 const date=new Date();form.elements.deadline.min=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
 form.addEventListener('submit',async e=>{
  e.preventDefault();if(form.elements.website.value)return;
  const button=form.querySelector('button[type=submit]'),status=document.querySelector('#form-status');
  const data=Object.fromEntries(new FormData(form));delete data.website;data.consent=true;data.deadline=data.deadline||null;data.id=enquiryId;data.enquiry_type=(form.elements.service.value===service&&requested?requested:form.elements.service.value).slice(0,150);
  data.service=SERVICE_CATEGORIES[data.service]||data.service;
  for(const key of ['name','email','phone','destination','message'])data[key]=data[key].trim();
  if(data.name.length<2){status.textContent='Please enter your full name.';return;}
  button.disabled=true;status.textContent='Sending your enquiry…';
  try{
   const r=await fetch(API+'/rest/v1/djp_enquiries',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(data),signal:AbortSignal.timeout(20000)});
   if(!r.ok)throw new Error('Unable to send');
   const refResponse=await fetch(API+'/rest/v1/rpc/djp_public_reference',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({p_id:enquiryId}),signal:AbortSignal.timeout(10000)});
   const leadRef=refResponse.ok?await refResponse.json():null;
   status.textContent='Enquiry received. Your reference is '+(leadRef||'pending confirmation')+'. DJP can now review your request and contact you using the details provided.';
   form.reset();enquiryId=crypto.randomUUID();
  }catch{status.textContent='We could not confirm your enquiry. Your details are still here. Please try again. If you already submitted, keep this reference: '+enquiryId;}
  finally{button.disabled=false;}
 });
}
let session=null;
const login=document.querySelector('#login');
if(login){
 login.addEventListener('submit',async e=>{
  e.preventDefault();const status=document.querySelector('#login-status'),b=login.querySelector('button');b.disabled=true;status.textContent='Signing in…';
  try{
   const r=await fetch(API+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(login))),signal:AbortSignal.timeout(20000)});
   const data=await r.json();if(!r.ok)throw new Error('Check your email and password, then try again.');
   if(data.user?.id!==OWNER){await fetch(API+'/auth/v1/logout',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+data.access_token}});throw new Error('This account does not have access to the DJP inbox.');}
   session=data;login.reset();login.hidden=true;document.querySelector('#inbox').hidden=false;await loadInbox();
  }catch(err){status.textContent=err.message||'Sign-in is unavailable. Try again.';}finally{b.disabled=false;}
 });
 document.querySelector('#refresh').addEventListener('click',loadInbox);
 document.querySelector('#logout').addEventListener('click',async()=>{if(session)await fetch(API+'/auth/v1/logout',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token}}).catch(()=>{});session=null;document.querySelector('#enquiries').replaceChildren();document.querySelector('#inbox').hidden=true;login.hidden=false;document.querySelector('#login-status').textContent='Signed out.';});
}


async function djpFetchDocuments(enquiryId){
 const filter=enquiryId?'&enquiry_id=eq.'+encodeURIComponent(enquiryId):'';
 const r=await fetch(API+'/rest/v1/djp_lead_documents?select=*&order=created_at.desc&limit=1000'+filter,{headers:{apikey:KEY,Authorization:'Bearer '+session.access_token}});
 if(!r.ok)throw new Error('Could not retrieve stored files ('+r.status+').');return r.json();
}
async function djpUploadDocument(id,file){
 if(file.size>10485760||!['application/pdf','image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Only PDF, JPG, PNG and WebP up to 10 MB are supported.');
 const path=id+'/'+crypto.randomUUID()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-90);
 const r=await fetch(API+'/storage/v1/object/djp-client-documents/'+path,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':file.type},body:file});
 if(!r.ok)throw new Error('File upload failed ('+r.status+').');
 const meta=await fetch(API+'/rest/v1/djp_lead_documents',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({enquiry_id:id,storage_path:path,file_name:file.name,file_size:file.size,content_type:file.type})});
 if(!meta.ok)throw new Error('File uploaded but could not be added to the client record.');
}
function djpDocumentRow(doc,refresh){
 const line=djpNode('div','lead-document-row'),open=djpNode('button','lead-document-link',doc.file_name),del=djpNode('button','lead-document-delete','Delete');
 open.type=del.type='button';
 open.addEventListener('click',async()=>{try{
  const r=await fetch(API+'/storage/v1/object/sign/djp-client-documents/'+doc.storage_path,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:60})});
  if(!r.ok)throw Error('Cannot open file.');const signed=await r.json();window.open(API+'/storage/v1'+signed.signedURL,'_blank','noopener,noreferrer');
 }catch(e){alert(e.message);}});
 del.addEventListener('click',async()=>{if(!confirm('Delete '+doc.file_name+' permanently?'))return;del.disabled=true;try{
  const r=await fetch(API+'/storage/v1/object/djp-client-documents/'+doc.storage_path,{method:'DELETE',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token}});
  if(!r.ok)throw Error('Could not delete file.');
  const m=await fetch(API+'/rest/v1/djp_lead_documents?id=eq.'+doc.id,{method:'DELETE',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token}});
  if(!m.ok)throw Error('Could not remove file record.');await refresh();
 }catch(e){alert(e.message);}finally{del.disabled=false;}});
 line.append(open,del);return line;
}
let djpStoredDocs=[];
async function djpLoadStoredFiles(){
 const status=document.querySelector('#files-status');status.textContent='Loading stored files…';
 try{djpStoredDocs=await djpFetchDocuments();djpRenderStoredFiles();}catch(e){status.textContent=e.message;}
}
function djpRenderStoredFiles(){
 const root=document.querySelector('#files-results'),term=document.querySelector('#file-search').value.trim().toLowerCase(),date=document.querySelector('#file-date').value;root.replaceChildren();
 const matched=djpStoredDocs.filter(doc=>{
  const lead=leadRows.find(r=>r.id===doc.enquiry_id);
  const searchable=[doc.file_name,lead?.name,lead?.email,lead?.lead_number?'DJP NQ'+lead.lead_number:'',lead?.id].join(' ').toLowerCase();
  return (!term||searchable.includes(term))&&(!date||doc.created_at.slice(0,10)===date);
 });
 document.querySelector('#files-status').textContent=matched.length+' matching files';
 matched.forEach(doc=>{const lead=leadRows.find(r=>r.id===doc.enquiry_id),card=djpNode('article','lead-card');
  card.append(djpNode('strong','',lead?.name||'Client'),djpNode('p','',lead?.lead_number?'DJP NQ'+lead.lead_number:'Lead reference unavailable'),djpNode('p','','Uploaded '+new Date(doc.created_at).toLocaleDateString('en-ZA')),djpDocumentRow(doc,djpLoadStoredFiles));root.append(card);
 });
}
if(login){
 document.querySelector('#show-leads')?.addEventListener('click',()=>{document.querySelector('#enquiries').hidden=false;document.querySelector('#stored-files').hidden=true;});
 document.querySelector('#show-files')?.addEventListener('click',()=>{document.querySelector('#enquiries').hidden=true;document.querySelector('#stored-files').hidden=false;djpLoadStoredFiles();});
 document.querySelector('#files-refresh')?.addEventListener('click',djpLoadStoredFiles);
 document.querySelector('#file-search')?.addEventListener('input',djpRenderStoredFiles);
 document.querySelector('#file-date')?.addEventListener('change',djpRenderStoredFiles);
}

const DJP_STATES=['New','Contacted','In progress','Closed'];
const DJP_COLORS={'New':'#d9f4df','Contacted':'#fff1b8','In progress':'#e9ddff','Closed':'#ffd9e9'};
let leadRows=[],activeLeadFilter='All';
async function djpPatch(id,changes){
 const r=await fetch(API+'/rest/v1/djp_enquiries?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(changes)});
 if(!r.ok)throw new Error('Could not save changes ('+r.status+').');
 const rows=await r.json();if(rows.length!==1)throw new Error('Update was not confirmed.');
 return rows[0];
}
function djpNode(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function djpField(label,value,type='text'){
 const wrap=djpNode('label','lead-field'),title=djpNode('span','',label),field=document.createElement(type==='textarea'?'textarea':'input');
 if(type!=='textarea')field.type=type;field.value=value??'';if(type==='textarea')field.rows=3;
 wrap.append(title,field);return {wrap,field};
}
function renderDjpLeads(){
 const root=document.querySelector('#enquiries');root.replaceChildren();
 const bar=djpNode('div','lead-filters');
 ['All',...DJP_STATES].forEach(s=>{const b=djpNode('button','lead-filter'+(s===activeLeadFilter?' selected':''),s+' ('+(s==='All'?leadRows.length:leadRows.filter(r=>r.status===s).length)+')');b.type='button';if(DJP_COLORS[s])b.style.background=DJP_COLORS[s];b.addEventListener('click',()=>{activeLeadFilter=s;renderDjpLeads();});bar.append(b);});
 root.append(bar);
 const matches=leadRows.filter(r=>activeLeadFilter==='All'||r.status===activeLeadFilter);
 if(!matches.length)root.append(djpNode('p','','No leads in this section.'));
 matches.forEach(row=>{
  const card=djpNode('article','lead-card'),head=djpNode('div','lead-head');
  const left=djpNode('div');left.append(djpNode('strong','',row.lead_number?'DJP NQ'+row.lead_number:'Enquiry pending reference'),djpNode('h3','',row.name),djpNode('p','',row.enquiry_type||row.service));
  const select=djpNode('select','lead-status');DJP_STATES.forEach(s=>{const opt=document.createElement('option');opt.value=s;opt.textContent=s;select.append(opt);});select.value=row.status;select.style.background=DJP_COLORS[row.status]||'#eee';
  select.addEventListener('change',async()=>{const prev=row.status;select.disabled=true;try{const updated=await djpPatch(row.id,{status:select.value});Object.assign(row,updated);renderDjpLeads();}catch(err){select.value=prev;document.querySelector('#inbox-status').textContent=err.message;}finally{select.disabled=false;}});
  head.append(left,select);card.append(head);
  const meta=djpNode('p','lead-meta','Received '+new Date(row.created_at).toLocaleString('en-ZA')+' · '+row.email+(row.phone?' · '+row.phone:'')+' · '+(row.destination||'Destination not specified'));
  card.append(meta);
  const detail=djpNode('details','lead-details'),summary=djpNode('summary','','View lead & manage customer');detail.append(summary);
  const body=djpNode('div','lead-body');
  body.append(djpNode('p','','Customer message: '+(row.message||'No message provided.')));
  body.append(djpNode('p','','Preferred deadline: '+(row.deadline||'Not specified')));
  const grid=djpNode('div','lead-grid');
  const fields=[
   ['contacted_by','Consultant who contacted the customer','text'],
   ['taken_over_by','Consultant who took over the lead','text'],
   ['closed_by','Consultant who closed the sale','text'],
   ['client_details','Additional customer details','textarea'],
   ['requested_documents','Documents requested / received (one per line)','textarea'],
   ['quotation_amount','Quotation amount (ZAR)','number'],
   ['payment_method','Payment method','select'],
   ['internal_notes','Internal follow-up notes','textarea']
  ];
  const controls={};
  fields.forEach(([key,label,type])=>{
   const f=djpField(label,row[key]??'',type==='select'?'text':type);
   if(type==='select'){const sel=document.createElement('select');['','EFT','Cash','Card','Payment link','Other'].forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v||'Select payment method';sel.append(o);});sel.value=row[key]||'';f.field.replaceWith(sel);f.field=sel;}
   if(key==='quotation_amount'){f.field.min='0';f.field.step='0.01';}
   controls[key]=f.field;grid.append(f.wrap);
  });
  body.append(grid);
  const uploads=djpNode('section','lead-uploads');
  uploads.append(djpNode('h3','','Client documents'));
  const choose=document.createElement('input');choose.type='file';choose.multiple=true;choose.accept='.pdf,.jpg,.jpeg,.png,.webp';
  const upload=djpNode('button','button secondary','Upload selected files');upload.type='button';
  const fileMessage=djpNode('p','','Private storage · PDF or images · 10 MB maximum each');
  const fileList=djpNode('div','');
  uploads.append(choose,upload,fileMessage,fileList);body.append(uploads);
  async function refreshLeadFiles(){
   const docs=await djpFetchDocuments(row.id);fileList.replaceChildren();
   if(!docs.length)fileList.append(djpNode('p','','No documents uploaded for this client.'));
   docs.forEach(doc=>fileList.append(djpDocumentRow(doc,refreshLeadFiles)));
  }
  detail.addEventListener('toggle',()=>{if(detail.open)refreshLeadFiles().catch(e=>fileMessage.textContent=e.message);});
  upload.addEventListener('click',async()=>{
   if(!choose.files.length){fileMessage.textContent='Select one or more documents first.';return;}
   upload.disabled=true;
   try{for(const file of choose.files)await djpUploadDocument(row.id,file);
    choose.value='';fileMessage.textContent='Documents uploaded successfully.';await refreshLeadFiles();
   }catch(e){fileMessage.textContent=e.message;}finally{upload.disabled=false;}
  });
  const actions=djpNode('div','lead-actions'),save=djpNode('button','button','Save customer details'),notice=djpNode('span','lead-save-message','');
  save.type='button';save.addEventListener('click',async()=>{
   save.disabled=true;notice.textContent='Saving…';
   try{const payload={};for(const [key,field] of Object.entries(controls))payload[key]=key==='quotation_amount'?(field.value===''?null:Number(field.value)):field.value;
    const updated=await djpPatch(row.id,payload);Object.assign(row,updated);notice.textContent='Saved successfully.';}
   catch(err){notice.textContent=err.message;}finally{save.disabled=false;}
  });
  actions.append(save,notice);body.append(actions);
  if(!['Contacted','In progress'].includes(row.status))body.insertBefore(djpNode('p','lead-hint','Customer details can be completed when this lead moves to Contacted or In progress.'),grid);
  detail.append(body);card.append(detail);root.append(card);
 });
}
async function loadInbox(){
 const status=document.querySelector('#inbox-status');status.textContent='Loading leads…';
 try{const r=await fetch(API+'/rest/v1/djp_enquiries?select=*&order=created_at.desc&limit=500',{headers:{apikey:KEY,Authorization:'Bearer '+session.access_token},signal:AbortSignal.timeout(20000)});
  if(!r.ok)throw new Error('Unable to load leads ('+r.status+').');leadRows=await r.json();status.textContent=leadRows.length+' leads in tracker';renderDjpLeads();
 }catch(err){status.textContent=err.message;}
}


