const serviceUrl=s=>s.url||'/djp/visa.html?service='+encodeURIComponent(s.slug);
const nav=document.querySelector('nav');
if(nav){
 nav.querySelectorAll('.nav-dropdown').forEach((dropdown,index)=>{
  dropdown.setAttribute('name','djp-service-navigation');
  dropdown.addEventListener('click',event=>{
   if(event.target.closest('summary')){
    const opening=!dropdown.open;
    nav.querySelectorAll('.nav-dropdown').forEach(other=>{if(other!==dropdown)other.open=false;});
    try{sessionStorage.setItem('djp-open-service-menu',opening?String(index):'');}catch{}
   }
  });
  dropdown.addEventListener('toggle',()=>{
   if(dropdown.open)nav.querySelectorAll('.nav-dropdown').forEach(other=>{if(other!==dropdown)other.open=false;});
  });
 });
 try{
  const saved=sessionStorage.getItem('djp-open-service-menu');
  if(saved!==null&&saved!==''){const d=nav.querySelectorAll('.nav-dropdown')[Number(saved)];if(d)d.open=true;}
 }catch{}
 nav.addEventListener('keydown',event=>{if(event.key==='Escape'){nav.querySelectorAll('.nav-dropdown').forEach(d=>d.open=false);try{sessionStorage.removeItem('djp-open-service-menu');}catch{}}});
}
document.querySelectorAll('a[href*="#learn-"]').forEach(a=>{
 const slug=a.getAttribute('href').split('#learn-')[1];const s=DJP_SERVICES.find(x=>x.slug===slug);
 if(s)a.href=serviceUrl(s);
});
document.querySelectorAll('.destinations a').forEach(a=>{
 const current=new URL(a.href);const dest=current.searchParams.get('destination');
 const names={'United States':'USA visa','United Kingdom':'UK visa','Schengen area':'Schengen visa'};
 const s=DJP_SERVICES.find(x=>x.name===(names[dest]||(dest+' visa')));if(s)a.href=serviceUrl(s);
});
const selectedSlug=new URLSearchParams(location.search).get('service');
if(selectedSlug&&location.pathname.endsWith('visa.html')){
 const selected=DJP_SERVICES.find(s=>s.slug===selectedSlug);
 const main=document.querySelector('#main');main.replaceChildren();
 const add=(parent,tag,text,className)=>{const el=document.createElement(tag);if(text)el.textContent=text;if(className)el.className=className;parent.append(el);return el;};
 const link=(parent,text,url,className)=>{const a=add(parent,'a',text,className);a.href=url;return a;};
 if(selected&&selected.overview){
  document.title=selected.name+' | DJP — Document Journey Processing';
  const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=selected.description;
  const hero=add(main,'section',null,'inner-hero');
  add(hero,'div','DJP / '+selected.category.toUpperCase(),'eyebrow');
  add(hero,'h1',selected.name);
  add(hero,'p',selected.description);
  const actions=add(hero,'div',null,'actions');
  link(actions,'Enquire about this service ↗',selected.enquire,'button');
  link(actions,'All services', '/djp/visa.html','text-link');
  const layout=add(main,'section',null,'section service-detail-layout');
  const article=add(layout,'article',null,'service-detail-copy');
  add(article,'h2',selected.heading);
  add(article,'p',selected.overview);
  add(article,'h3','What to prepare');
  const ul=add(article,'ul');selected.prepare.forEach(item=>add(ul,'li',item));
  add(article,'p','Share a brief outline in the initial enquiry. DJP will discuss the appropriate way to provide supporting paperwork after the request has been reviewed.');
  add(article,'h3','The process');
  add(article,'p',selected.process);
  add(article,'h3','How DJP can assist');
  add(article,'p','Discuss the administrative support you need: organising the request, reviewing the document list, identifying missing information and planning agreed submission, follow-up or delivery arrangements. The available service and any specialist involvement are confirmed for your individual request.');
  add(article,'h3','Fees and turnaround');
  add(article,'p','Ask for a written quote setting out DJP assistance fees and any official, third-party or courier charges. Explain your deadline at the start so timing can be considered. Availability, required checks and authority processing affect the overall schedule; your enquiry does not confirm a booking.');
  add(article,'h3',selected.faqQuestion);
  add(article,'p',selected.faqAnswer);
  if(selected.source){add(article,'h3','Official information');link(article,'Read the relevant authority’s guidance ↗',selected.source,'text-link');}
  const aside=add(layout,'aside',null,'service-detail-aside');
  add(aside,'div','YOUR NEXT STEP','eyebrow');
  add(aside,'h3','Let’s discuss your request.');
  add(aside,'p','Tell us the service, your current location, destination and preferred deadline. We will help you understand what to prepare next.');
  link(aside,'Start an enquiry ↗',selected.enquire,'button');
  link(aside,'Email DJP','mailto:docjprocessing@gmail.com','text-link');
  add(aside,'p','Keep passport numbers, identity documents, fingerprints and sensitive personal records out of the initial message.','fine');
  const related=add(main,'section',null,'section');
  add(related,'h2','Related services');
  const tags=add(related,'div',null,'service-tags');
  DJP_SERVICES.filter(s=>s.category===selected.category&&s.slug!==selected.slug).slice(0,6).forEach(s=>link(tags,s.name+' ↗',serviceUrl(s)));
 }else{
  const section=add(main,'section',null,'section prose');add(section,'h1','Choose a service');add(section,'p','We could not find that service. Please choose from the service directory.');link(section,'View all services','/djp/visa.html','button');
 }
 window.scrollTo(0,0);
}
